tool_input.command:
cat > /tmp/test-sdk.mjs << 'EOF'
import { Eval } from 'frai-core';

const outputs = ['hello', 'world', 'test'];
const references = ['hello', 'world', 'example'];

const evaluations = Eval.runEvaluations({ outputs, references });
console.log('Evaluations:', JSON.stringify(evaluations, null, 2));

const report = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/references.json',
  thresholds: {
    exact_match: 0.5,
    length_variance: 0.9
  }
});

console.log('\nReport with thresholds:');
console.log(JSON.stringify(report, null, 2));
EOF
node --input-type=module /tmp/test-sdk.mjs
